{
  "criteria": [
    {
      "kind": "inclusion",
      "text": "Histopathologically-confirmed diagnosis of malignant melanoma that is metastatic or unresectable at Screening.",
      "quote": "Histopathologically-confirmed diagnosis of malignant melanoma that is metastatic or unresectable at Screening."
    },
    {
      "kind": "inclusion",
      "text": "Known BRAF mutation status; if BRAF V600 mutation positive, must have had prior treatment with a local Health Authority approved BRAF inhibitor, with or without MEK inhibitor. Patients with BRAF V600 mutations who refuse a BRAF inhibitor will not be eligible.",
      "quote": "Known BRAF mutation status; if BRAF V600 mutation positive, must have had prior treatment with a local Health Authority approved BRAF inhibitor, with or without MEK inhibitor."
    },
    {
      "kind": "inclusion",
      "text": "Refractory to PD-1 blockade either as monotherapy or in combination with other therapies, as defined by: received treatment with a Food and Drug Administration approved PD-1 blocking antibody for 12 weeks or longer; have PD (according to RECIST v1.1) within 12 weeks of the last dose of a PD-1 blocking antibody, either as monotherapy or in combination with other agents. Evidence of confirmed PD must be established by Investigator assessment at least 4 weeks after the initial date of PD. The confirmatory assessment may serve as the Baseline for this study if completed within 30 days before the start of study treatment. NOTE: in subjects with histologically confirmed recurrence on or after adjuvant PD-1 blocking antibody, confirmatory imaging is not required.",
      "quote": "Refractory to PD-1 blockade either as monotherapy or in combination with other therapies, as defined by the following criteria: a. Received treatment with a Food and Drug Administration approved PD-1 blocking antibody for 12 weeks or longer. b. Have PD (according to RECIST v1.1) within 12 weeks of the last dose of a PD-1 blocking antibody, either as monotherapy or in combination with other agents."
    },
    {
      "kind": "inclusion",
      "text": "Measurable disease, as defined by RECIST v1.1 and all of the following: at least 1 accessible lesion amenable to repeated IT injection; one or more measurable lesions at least 1 cm in diameter that are not intended for CMP-001 injection and can be followed as target lesions per RECIST v1.1; documented disease progression in any lesion that was previously radiated in order to serve as a target lesion.",
      "quote": "Measurable disease, as defined by RECIST v1.1 and all of the following: a. At least 1 accessible lesion amenable to repeated IT injection. b. One or more measurable lesions at least 1 cm in diameter that are not intended for CMP-001 injection and can be followed as target lesions per RECIST v1.1. c. Documented disease progression in any lesion that was previously radiated in order to serve as a target lesion."
    },
    {
      "kind": "inclusion",
      "text": "Able to provide tissue from a core or excisional/incisional biopsy (fine needle aspirate is not sufficient). A fresh tissue biopsy (within 90 days before the start of study treatment) is preferred but an archival sample is acceptable (as a substitute) if no intervening therapy was received. If the Investigator believes it is unsafe to perform a biopsy, the subject may be considered eligible after discussion with the Medical Monitor if tissue and/or prior assessments are available to determine programmed death-ligand 1 expression.",
      "quote": "Able to provide tissue from a core or excisional/incisional biopsy (fine needle aspirate is not sufficient)."
    },
    {
      "kind": "inclusion",
      "text": "Adequate organ function based on most recent laboratory values within 3 weeks before first dose of study treatment on Week 1 Day 1 (W1D1): Bone marrow function: neutrophil count ≥ 1500/mm3, platelet count ≥ 100,000/mm3, hemoglobin concentration ≥ 9 g/dL, white blood cells ≥ 2000/mm3. Liver function: total bilirubin ≤ 1.5 times the upper limit of normal (ULN) with the following exception: subjects with Gilbert Disease total serum bilirubin ≤ 3 times ULN; aspartate aminotransferase and alanine aminotransferase ≤ 3 times the ULN. Lactate dehydrogenase ≤ 2 times the ULN. Renal function: estimated (Cockcroft-Gault) or measured creatinine clearance ≥ 30 mL/min. Coagulation: International normalized ratio or prothrombin time (PT) ≤ 1.5 times ULN, unless subject is receiving anticoagulant therapy, as long as PT or partial thromboplastin time (PTT) is within therapeutic range of intended use of anticoagulants; Activated partial thromboplastin time or PTT ≤ 1.5 times ULN, unless subject is receiving anticoagulant therapy, as long as PT or PTT is within therapeutic range of intended use of anticoagulants.",
      "quote": "Adequate organ function based on most recent laboratory values within 3 weeks before first dose of study treatment on Week 1 Day 1 (W1D1):",
      "thresholds": [
        {"test": "neutrophil count", "op": ">=", "value": 1500, "unit": "/mm3"},
        {"test": "platelet count", "op": ">=", "value": 100000, "unit": "/mm3"},
        {"test": "hemoglobin", "op": ">=", "value": 9, "unit": "g/dL"},
        {"test": "white blood cells", "op": ">=", "value": 2000, "unit": "/mm3"},
        {"test": "total bilirubin", "op": "<=", "value": 1.5, "unit": "x ULN"},
        {"test": "total serum bilirubin (Gilbert Disease)", "op": "<=", "value": 3, "unit": "x ULN"},
        {"test": "aspartate aminotransferase", "op": "<=", "value": 3, "unit": "x ULN"},
        {"test": "alanine aminotransferase", "op": "<=", "value": 3, "unit": "x ULN"},
        {"test": "lactate dehydrogenase", "op": "<=", "value": 2, "unit": "x ULN"},
        {"test": "creatinine clearance", "op": ">=", "value": 30, "unit": "mL/min"},
        {"test": "INR or PT", "op": "<=", "value": 1.5, "unit": "x ULN"},
        {"test": "aPTT or PTT", "op": "<=", "value": 1.5, "unit": "x ULN"}
      ]
    },
    {
      "kind": "inclusion",
      "text": "Age ≥ 21 years at time of consent.",
      "quote": "Age ≥ 21 years at time of consent.",
      "thresholds": [{"test": "age", "op": ">=", "value": 21, "unit": "years"}]
    },
    {
      "kind": "inclusion",
      "text": "Eastern Cooperative Oncology Group Performance Status of 0 to 1 at Screening.",
      "quote": "Eastern Cooperative Oncology Group Performance Status of 0 to 1 at Screening."
    },
    {
      "kind": "inclusion",
      "text": "Capable of understanding and complying with protocol requirements.",
      "quote": "Capable of understanding and complying with protocol requirements."
    },
    {
      "kind": "inclusion",
      "text": "Women of childbearing potential must have negative serum pregnancy test before dosing at W1D1 and be willing to use an adequate method of contraception (Section 4.3.2.) from the time of consent until at least 150 days after last dose of study treatment.",
      "quote": "Women of childbearing potential must have negative serum pregnancy test before dosing at W1D1 and be willing to use an adequate method of contraception (Section 4.3.2.) from the time of consent until at least 150 days after last dose of study treatment."
    },
    {
      "kind": "inclusion",
      "text": "Able and willing to provide written informed consent and to follow study instructions. Subjects unable to provide written informed consent on their own behalf will not be eligible for the study.",
      "quote": "Able and willing to provide written informed consent and to follow study instructions."
    }
  ]
}
